        '＝': '=', // U+FF1D 全角等号
        '＞': '>', // U+FF1E 全角大于号
        '＜': '<', // U+FF1C 全角小于号
        '＋': '+', // U+FF0B 全角加号
        '－': '-', // U+FF0D 全角减号
        '＊': '*', // U+FF0A 全角星号
        '／': '/', // U+FF0F 全角斜杠
        // 括号
        '（': '(', // U+FF08 全角左括号
        '）': ')', // U+FF09 全角右括号
        // 标点
        '，': ',', // U+FF0C 全角逗号
        '；': ';', // U+FF1B 全角分号
