        // 填充：1 字节 0x80 + 若干 0x00 + 8 字节大端比特长度，总长为 64 的整数倍。
        const paddedLength = (((input.length + 9) + 63) >> 6) << 6;
        const padded = new Uint8Array(paddedLength);
