                backend: 'st-files',
                status: 'ready',
                indexId,
                snapshotMessageId: options.snapshotMessageId,
                sourceTableKey: options.sourceTableKey,
                sourceTableName: options.sourceTableName,
                indexedAt,
                rowCount: rowsWithShardIds.length,
                chunkCount: chunks.length,
