        const bucket = readIdentityBucket_ACU(sheetKey, resolvedContent) || emptyV2Bucket_ACU();
        const existing = bucket.colNames.indexOf(colName);
        if (existing >= 0)
            bucket.colNames.splice(existing, 1);
