    class TableUpdateCommitError_ACU extends Error {
        constructor(message, category) {
            super(message);
            this.category = category;
            this.name = 'TableUpdateCommitError';
        }
    }
    function cloneTableData_ACU(data) {
        return JSON.parse(JSON.stringify(data));
    }
