        //
        // const threshold = settings_ACU.autoMergeThreshold || 20;
        // const reserve = settings_ACU.autoMergeReserve || 0;
        // const triggerThreshold = threshold + reserve;
        //
        // if (summaryCount < triggerThreshold) return { shouldTrigger: false };
        //
