        if (!globalEnabled) {
            logDebug_ACU(`[交火模式纪要索引] 全局开关未启用，跳过发送前处理。worldbookProjection=${worldbookConfig.summaryVectorIndexModeEnabled === true}`);
            return { success: false, skipped: true, reason: 'summary_vector_index_disabled' };
        }
